pub fn go_package_name(module_name: String) -> String {
    {
        let parts = Rc::new(
            module_name
                .clone()
                .split(&".".to_string())
                .map(|s| s.to_string())
                .collect::<Vec<_>>(),
        );
        match parts.clone().last().cloned() {
            Some(last_part) => Rc::new({
                let mut __result = Vec::new();
                for c in Rc::new(
                    last_part
                        .clone()
                        .chars()
                        .map(|c| c as i64)
                        .collect::<Vec<_>>(),
                )
                .iter()
                .cloned()
                {
                    __result.push(crate::v1_compiler_emit_core_support::to_lower_char(
                        c.clone(),
                    ));
                }
                __result
            })
            .join(&"".to_string()),
            None => "main".to_string(),
        }
    }
}

