pub fn emit_go_rest_call(
    op_name: String,
    transport: Rc<Node>,
    depth: i64,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let prefix = crate::v1_compiler_emit_core_support::make_indent(depth.clone());
        let url_line = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(prefix.clone(), "url := fmt.Sprintf(\"%s/".to_string()),
                crate::v1_compiler_emit_core_support::to_snake(op_name.clone()),
            ),
            "\", c.BaseURL)".to_string(),
        );
        let body_line = v1_rt::concat(
            prefix.clone(),
            "reqBody := bytes.NewBuffer(nil)".to_string(),
        );
        let req_line = v1_rt::concat(
            v1_rt::concat(
                prefix.clone(),
                "req, err := http.NewRequest(\"POST\", url, reqBody)\n".to_string(),
            ),
            "if err != nil {\n\treturn nil, fmt.Errorf(\"creating request: %w\", err)\n}"
                .to_string(),
        );
        let auth_line =
            if crate::v1_std_core::transport_has_auth(transport.clone(), source_indices.clone()) {
                {
                    let header_name = match crate::v1_std_core::transport_auth_header_name(
                        transport.clone(),
                        source_indices.clone(),
                    ) {
                        Some(h) => h.clone(),
                        None => "Authorization".to_string(),
                    };
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(prefix.clone(), "req.Header.Set(\"".to_string()),
                            header_name.clone(),
                        ),
                        "\", c.AuthToken)".to_string(),
                    )
                }
            } else {
                "".to_string()
            };
        let hdrs = crate::v1_std_core::transport_headers(transport.clone(), source_indices.clone());
        let header_lines = Rc::new({
            let mut __result = Vec::new();
            for h in hdrs.clone().iter().cloned() {
                __result.push(v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(prefix.clone(), "req.Header.Set(\"".to_string()),
                                crate::v1_std_core::field_init_node_name_at(
                                    h.clone(),
                                    source_indices.clone(),
                                ),
                            ),
                            "\", ".to_string(),
                        ),
                        crate::v1_compiler_emit::emit_simple_expr(
                            crate::v1_std_core::field_init_node_value(h.clone()),
                            RenderTarget::Go,
                            source_indices.clone(),
                        ),
                    ),
                    ")".to_string(),
                ));
            }
            __result
        });
        let send_lines = v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(prefix.clone(), "resp, err := http.DefaultClient.Do(req)\n".to_string()), "if err != nil {\n\treturn nil, fmt.Errorf(\"sending request: %w\", err)\n}\n".to_string()), "defer resp.Body.Close()\n".to_string()), "body, err := io.ReadAll(resp.Body)\n".to_string()), "if err != nil {\n\treturn nil, fmt.Errorf(\"reading response: %w\", err)\n}\n".to_string()), "var result interface{}\n".to_string()), "if err := json.Unmarshal(body, &result); err != nil {\n".to_string()), "\treturn nil, fmt.Errorf(\"decoding response: %w\", err)\n}\n".to_string()), "return result, nil".to_string());
        let all_lines = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    Rc::new(vec![url_line.clone(), body_line.clone(), req_line.clone()]),
                    if (auth_line.clone() == "".to_string()) {
                        Rc::new(vec![])
                    } else {
                        Rc::new(vec![auth_line.clone()])
                    },
                ),
                header_lines.clone(),
            ),
            Rc::new(vec![send_lines.clone()]),
        );
        all_lines.clone().join(&"\n".to_string())
    }
}

pub fn emit_go_shell_call(
    op_name: String,
    transport: Rc<Node>,
    depth: i64,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let prefix = crate::v1_compiler_emit_core_support::make_indent(depth.clone());
        let cmd_line = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(prefix.clone(), "cmd := exec.Command(\"".to_string()),
                crate::v1_compiler_emit_core_support::to_snake(op_name.clone()),
            ),
            "\")".to_string(),
        );
        let dir_line = v1_rt::concat(prefix.clone(), "cmd.Dir = c.WorkingDir".to_string());
        let envs = crate::v1_std_core::transport_env(transport.clone(), source_indices.clone());
        let env_lines = Rc::new({
            let mut __result = Vec::new();
            for e in envs.clone().iter().cloned() {
                __result.push(v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    prefix.clone(),
                                    "cmd.Env = append(cmd.Env, \"".to_string(),
                                ),
                                crate::v1_std_core::field_init_node_name_at(
                                    e.clone(),
                                    source_indices.clone(),
                                ),
                            ),
                            "=\" + ".to_string(),
                        ),
                        crate::v1_compiler_emit::emit_simple_expr(
                            crate::v1_std_core::field_init_node_value(e.clone()),
                            RenderTarget::Go,
                            source_indices.clone(),
                        ),
                    ),
                    ")".to_string(),
                ));
            }
            __result
        });
        let run_lines = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(prefix.clone(), "output, err := cmd.Output()\n".to_string()),
                "if err != nil {\n\treturn \"\", fmt.Errorf(\"running command: %w\", err)\n}\n"
                    .to_string(),
            ),
            "return string(output), nil".to_string(),
        );
        let all_lines = v1_rt::concat(
            v1_rt::concat(
                Rc::new(vec![cmd_line.clone(), dir_line.clone()]),
                env_lines.clone(),
            ),
            Rc::new(vec![run_lines.clone()]),
        );
        all_lines.clone().join(&"\n".to_string())
    }
}

pub fn emit_go_file_call(op_name: String, depth: i64) -> String {
    {
        let prefix = crate::v1_compiler_emit_core_support::make_indent(depth.clone());
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(prefix.clone(), "path := fmt.Sprintf(\"%s/".to_string()),
                            crate::v1_compiler_emit_core_support::to_snake(op_name.clone()),
                        ),
                        "\", c.BasePath)\n".to_string(),
                    ),
                    "data, err := os.ReadFile(path)\n".to_string(),
                ),
                "if err != nil {\n\treturn \"\", fmt.Errorf(\"reading file: %w\", err)\n}\n"
                    .to_string(),
            ),
            "return string(data), nil".to_string(),
        )
    }
}

pub fn emit_go_local_call(op_name: String, depth: i64) -> String {
    {
        let prefix = crate::v1_compiler_emit_core_support::make_indent(depth.clone());
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        prefix.clone(),
                        "// Local binding -- direct function call\n".to_string(),
                    ),
                    "return ".to_string(),
                ),
                go_export_ident(op_name.clone()),
            ),
            "(), nil".to_string(),
        )
    }
}

pub fn emit_go_resource_def(item: Rc<Node>, env: Rc<TypeEnv>) -> String {
    {
        let item_text = crate::v1_compiler_infer_env::authored_name(env.clone(), item.clone());
        let cap_children = Rc::new({
            let mut __result = Vec::new();
            for c in item.children.clone().iter().cloned() {
                if ((c.params.clone().len() as i64) > 0) {
                    __result.push(c);
                }
            }
            __result
        });
        let methods = Rc::new({
            let mut __result = Vec::new();
            for c in cap_children.clone().iter().cloned() {
                __result.push(emit_go_capability_method(c.clone(), 1, env.clone()));
            }
            __result
        });
        let methods_str = methods.clone().join(&"\n".to_string());
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            crate::v1_compiler_emit_core_support::language_spec(RenderTarget::Go)
                                .items
                                .clone()
                                .type_alias_keyword
                                .clone(),
                            " ".to_string(),
                        ),
                        item_text.clone(),
                    ),
                    " interface {\n".to_string(),
                ),
                methods_str.clone(),
            ),
            "\n}".to_string(),
        )
    }
}

pub fn emit_go_capability_method(cap_node: Rc<Node>, depth: i64, env: Rc<TypeEnv>) -> String {
    {
        let input_params = Rc::new({
            let mut __result = Vec::new();
            for p in cap_node.params.clone().iter().cloned() {
                __result.push(v1_rt::concat(
                    v1_rt::concat(
                        crate::v1_compiler_emit::emit_ident(
                            crate::v1_std_core::param_node_name_at(
                                p.clone(),
                                env.source_indices.clone(),
                            ),
                            RenderTarget::Go,
                        ),
                        " ".to_string(),
                    ),
                    crate::v1_compiler_emit::emit_node_type(
                        crate::v1_std_core::param_node_type_expr(p.clone()),
                        RenderTarget::Go,
                        env.source_indices.clone(),
                    ),
                ));
            }
            __result
        });
        let params_str = input_params.clone().join(&", ".to_string());
        let ret = crate::v1_compiler_emit::emit_node_type(
            crate::v1_compiler_infer_types::resolved_type(cap_node.clone()),
            RenderTarget::Go,
            env.source_indices.clone(),
        );
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                crate::v1_compiler_emit_core_support::make_indent(depth.clone()),
                                go_export_ident(crate::v1_compiler_infer_env::authored_name(
                                    env.clone(),
                                    cap_node.clone(),
                                )),
                            ),
                            "(".to_string(),
                        ),
                        params_str.clone(),
                    ),
                    ") (".to_string(),
                ),
                ret.clone(),
            ),
            ", error)".to_string(),
        )
    }
}

pub fn emit_go_data_def(
    name: String,
    type_node: Rc<Node>,
    value: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
) -> String {
    {
        let ty_str = crate::v1_compiler_emit::emit_node_type(
            type_node.clone(),
            RenderTarget::Go,
            scope.type_env.clone().source_indices.clone(),
        );
        let val_str = emit_go_typed_expr(
            value.clone(),
            registry.clone(),
            scope.clone(),
            depth.clone(),
            1024,
        );
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat("var ".to_string(), go_export_ident(name.clone())),
                        " ".to_string(),
                    ),
                    ty_str.clone(),
                ),
                " = ".to_string(),
            ),
            val_str.clone(),
        )
    }
}

pub fn go_export_ident(name: String) -> String {
    match (*crate::v1_compiler_emit_core_support::language_spec(RenderTarget::Go)
        .visibility
        .clone())
    .clone()
    {
        VisibilitySpec::CaseVisibility {
            export_case: ec, ..
        } => {
            let result = crate::v1_compiler_emit::apply_naming_case(name.clone(), ec.clone());
            if {
                let mut __found = false;
                for r in crate::extdeps_languages_go_emit::go_reserved()
                    .iter()
                    .cloned()
                {
                    if (r.clone() == result.clone()) {
                        __found = true;
                        break;
                    }
                }
                __found
            } {
                v1_rt::concat(
                    result.clone(),
                    crate::extdeps_languages_go_emit::go_reserved_escape_suffix(),
                )
            } else {
                result.clone()
            }
        }
        _ => "__GO_VISIBILITY_SPEC_MISMATCH__".to_string(),
    }
}
